847	size_t packcompact(unsigned char* compact, const std::string& addr,
848	                   uint16_t port)
849	{
850	  size_t len = net::getBinAddr(compact, addr);
851	  if (len == 0) {
852	    return 0;
853	  }
854	  uint16_t portN = htons(port);
855	  memcpy(compact + len, &portN, sizeof(portN));
856	  return len + 2;
857	}
