974	  for (auto& elem : attrs->announceList) {
975	    auto tier = List::g();
976	    for (auto& uri : elem) {
977	      tier->append(uri);
978	    }
979	    if (!tier->empty()) {
980	      announceList.append(std::move(tier));
981	    }
982	  }
