45	template <typename Parser, typename ParserStateMachine,
46	          bool allowEmptyName = false>
47	class GenericParser {
48	public:
49	  GenericParser() : parser_{&psm_}
50	  {
51	    psm_.setAllowEmptyMemberName(allowEmptyName);
52	  }
53	
54	  ~GenericParser() = default;
55	
56	  typedef typename ParserStateMachine::ResultType ResultType;
57	  typedef ParserStateMachine ParserStateMachineType;
58	
59	  // Parses |size| bytes of data |data| and returns the number of
60	  // bytes processed. On error, one of the negative error codes is
61	  // returned.
62	  ssize_t parseUpdate(const char* data, size_t size)
63	  {
64	    return parser_.parseUpdate(data, size);
65	  }
66	
67	  // Parses |size| bytes of data |data| and returns result. On error,
68	  // null value is returned. On success, the |error| will be the
69	  // number of bytes processed (>= 0). On error, it will be one of the
70	  // negative error code. This function also resets underlying parser
71	  // facility and make it ready to reuse.
72	  ResultType parseFinal(const char* data, size_t size, ssize_t& error)
73	  {
74	    ResultType res;
75	    error = parser_.parseFinal(data, size);
76	    if (error < 0) {
77	      res = ParserStateMachine::noResult();
78	    }
79	    else {
80	      res = psm_.getResult();
81	    }
82	    parser_.reset();
83	    return res;
84	  }
85	
86	private:
87	  ParserStateMachine psm_;
88	  Parser parser_;
89	};
