91	template <typename Parser>
92	typename Parser::ResultType parseFile(Parser& parser,
93	                                      const std::string& filename)
94	{
95	  int fd;
96	  // TODO Overrode a2open(const char*,..) and a2open(const std::wstring&,..)
97	  while ((fd = a2open(utf8ToWChar(filename).c_str(), O_BINARY | O_RDONLY,
98	                      OPEN_MODE)) == -1 &&
99	         errno == EINTR)
100	    ;
101	  if (fd == -1) {
102	    return Parser::ParserStateMachineType::noResult();
103	  }
104	  auto fdclose = defer(fd, close);
105	  std::array<char, 4_k> buf;
106	  ssize_t nread;
107	  ssize_t nproc;
108	  while ((nread = read(fd, buf.data(), buf.size())) > 0) {
109	    nproc = parser.parseUpdate(buf.data(), nread);
110	    if (nproc < 0) {
111	      break;
112	    }
113	  }
114	  return parser.parseFinal(0, 0, nproc);
115	}
